import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let ch: conc.Channel<Int64> = conc.channel(0)
    scope {
        let sender = task effect io {
            ch.send(9)
            io.println("sent")
        }
        let receiver = task effect io {
            let v = ch.receive()
            io.println("got")
        }
        let _ = sender.await()
        let _ = receiver.await()
    }
    return Ok(())
}
